// ── ITEM SPRITES (custom artwork) ────────────────────────────────────────
// To swap in new art, replace the base64 string for the relevant item.
// Each entry: label matching ITEMS_LAYOUT → base64 JPG/PNG data URI.
const ITEM_SPRITES = {};
(function(){
  const defs = {
    'MONA':  'data:image/png;base64,',
    'RADIO': 'data:image/png;base64,',
    'SAFE':  'data:image/png;base64,',
    'PC':    'data:image/png;base64,',
    'TV':    'data:image/png;base64,',
  };
  for(const [k,v] of Object.entries(defs)){
    const img = new Image();
    img.src = v;
    ITEM_SPRITES[k] = img;
  }
})();

